package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code identityKey} = normalized telephone + '|' + (lower-cased email or
 * empty) + '|' + household id. Duplicate detection is a single equality on this whole key, and it
 * is also returned on the owner. Two owners collide only when telephone, email and household all
 * match; sharing only a household (with different telephones) yields different keys.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(Owner owner) {
        String email = owner.getEmail() == null || owner.getEmail().isBlank()
                ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
    }
}
=== EnsureUniqueHousehold.java ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create request whose last name and address (compared case-insensitively with
 * collapsed whitespace) match an existing owner, so a household duplicate is a 409 via
 * {@link DuplicateHouseholdException}. A request that opts in with {@code sharesHousehold} true
 * is allowed through.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = normalize(request.getAddress());
        for (Owner owner : ownerRepository.findAll()) {
            if (lastName.equals(normalize(owner.getLastName())) && address.equals(normalize(owner.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
=== NormalizeAddress.java ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;

/**
 * Canonicalises the address whenever an owner is created: whitespace is trimmed and collapsed,
 * the text is upper-cased and common abbreviations are expanded ({@code ST}->{@code STREET},
 * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). The normalized value is stored back on
 * the request so it is persisted and returned as {@code address}, and so every downstream
 * comparison (household duplicate detection, the shared household id) sees the canonical form. An
 * address that is blank after normalization is rejected with 400 via {@link MissingFieldsException}.
 */
public class NormalizeAddress {

    public void service(@Val OwnerFieldsDto request) throws MissingFieldsException {
        String normalized = request.getAddress().trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT)
                .replaceAll("\\bST\\b", "STREET")
                .replaceAll("\\bRD\\b", "ROAD")
                .replaceAll("\\bAVE\\b", "AVENUE");
        if (normalized.isBlank()) {
            throw new MissingFieldsException(List.of("address"));
        }
        request.setAddress(normalized);
    }
}
