package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Objects;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

/**
 * Soft-match rule: an owner that is not a hard duplicate but shares another owner's last name and
 * postcode with a different telephone is flagged {@code possibleDuplicate}, with
 * {@code possibleDuplicateOf} set to that owner's id. Mirrors the response-time derivation used for
 * {@link BulkSignup}, so both the create and fetch responders report the same value.
 */
public final class PossibleDuplicate {

    private PossibleDuplicate() {
    }

    public static void mark(OwnerDto dto, Owner owner, OwnerRepository ownerRepository) {
        Integer matchId = matchingOwnerId(owner, ownerRepository);
        dto.setPossibleDuplicate(matchId != null);
        dto.setPossibleDuplicateOf(matchId);
    }

    private static Integer matchingOwnerId(Owner owner, OwnerRepository ownerRepository) {
        if (owner.getPostcode() == null) {
            return null;
        }
        String lastName = normalize(owner.getLastName());
        for (Owner other : ownerRepository.findAll()) {
            if (!Objects.equals(other.getId(), owner.getId())
                    && lastName.equals(normalize(other.getLastName()))
                    && owner.getPostcode().equals(other.getPostcode())
                    && !Objects.equals(owner.getTelephone(), other.getTelephone())) {
                return other.getId();
            }
        }
        return null;
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().toLowerCase();
    }
}
=== ValidatePostcode ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;
import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Locality;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;

/**
 * Validates an owner's optional postcode when present: it must be four digits and, when the city's
 * region is known, fall within that region's fixed range (NSW 2000-2099, VIC 3000-3099,
 * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An absent postcode is
 * left untouched, keeping the create request backward-compatible. A bad postcode is a 400 via
 * {@link MissingFieldsException}.
 */
public class ValidatePostcode {

    /** Region -> inclusive {low, high} 4-digit postcode range. */
    private static final Map<String, int[]> REGION_RANGES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    public void service(@Val OwnerFieldsDto request) throws MissingFieldsException {
        String postcode = request.getPostcode();
        if (postcode == null) {
            return;
        }
        int[] range = REGION_RANGES.get(Locality.of(request.getCity()));
        if (!postcode.matches("[0-9]{4}") || (range != null
                && (Integer.parseInt(postcode) < range[0] || Integer.parseInt(postcode) > range[1]))) {
            throw new MissingFieldsException(List.of("postcode"));
        }
    }
}

